package com.marketplatform.gateway.filter;

import org.springframework.cloud.gateway.filter.GatewayFilter;
import org.springframework.cloud.gateway.filter.factory.AbstractGatewayFilterFactory;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Component;

@Component
public class VendorRoutingFilter extends AbstractGatewayFilterFactory<VendorRoutingFilter.Config> {

    public VendorRoutingFilter() {
        super(Config.class);
    }

    @Override
    public GatewayFilter apply(Config config) {
        return (exchange, chain) -> ReactiveSecurityContextHolder.getContext()
                .map(sc -> (Jwt) sc.getAuthentication().getPrincipal())
                .flatMap(jwt -> {
                    String authorizedVendorId = jwt.getClaimAsString("vendorId");
                    var request = exchange.getRequest().mutate()
                            .header("X-Internal-Vendor-Id", authorizedVendorId)
                            .build();
                    return chain.filter(exchange.mutate().request(request).build());
                });
    }

    public static class Config {}
}
